practiceProblems.solutionCode:
public class Main {
    public static void main(String[] args) {
        double itemPrice = 1299.50;
        double discount = 150.25;
        double finalAmount = itemPrice - discount;
        System.out.println("Final Amount: Rs " + finalAmount);
    }
}

